#!/bin/zsh
# 第四部分生图（09-28）。用法：zsh draw_part4.sh <名字>   在项目根 ClaudePop_PDoom/ 下运行
cd "${0:A:h}/.."
STAGE=素材/角色/设定图_舞台服_v1.png
CLAWD=素材/群演/preview.png
TAIL='Hair in large clumps, thick clean dark-brown ink outlines, hard cel shading with 2 tones per color, white clothes shaded with cool lavender-grey, flat colors, no gradients, no airbrush, no screentone, no halftone, no paper texture.'
TAIL2='Hard cel shading with 2 tones per color, bold clean dark ink lines, flat colors, no gradients, no airbrush, no screentone, no halftone, no paper texture.'
case $1 in
# ---- Seedance 关键帧 ----
s1) xk-draw --ref $STAGE --size 1536x864 --out 素材/关键帧/p4_s1_背影全身.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9. Full-body shot of the girl from image 1 in the idol stage costume with headset microphone, SEEN FROM BEHIND: we see her back, the back of her long wavy peach-orange hair in large clumps, the orange ribbons and the back of her ruffled skirt and boots. The whole figure in frame from the top of her hair to her boots, standing a little right of center, feet apart in a powerful stance, her right gloved fist punched high up into the air, facing away from the viewer toward an unseen huge audience, her head turned very slightly so a sliver of her cheek shows. Background: flat plain deep indigo, completely empty. Her feet at about 80% of the frame height. Keep the left third of the frame empty. $TAIL No text." ;;
s2) xk-draw --ref $STAGE --size 1536x864 --out 素材/关键帧/p4_s2_谢幕全身.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9. Full-body shot of the girl from image 1 in the idol stage costume with headset microphone, the whole figure in frame from hair to boots, centered, facing the viewer at the final curtain call of her last concert: both gloved hands raised high waving goodbye, the happiest smile with shining teary eyes, a little out of breath, hair and ribbons settling. Background: flat plain deep wine red, completely empty. Her feet at about 80% of the frame height. $TAIL No text." ;;
# ---- CG（有限动画） ----
back_a) xk-draw --ref $STAGE --size 1536x864 --out 素材/CG/p4_5a_背影看台下_a.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9. Over-the-shoulder view from behind the girl from image 1 in the idol stage costume with headset microphone, shown from the waist up, on the right side of the frame, standing at the very front edge of a huge stage, looking out over a vast dark concert arena. Below and beyond her: an ocean of thousands of small glowing lightsticks in pink, cyan, yellow and purple dots receding into darkness, rows of dark audience silhouettes. Her arms hang loosely at her sides, head tilted slightly as if a doubt crossed her mind. Deep indigo darkness, a warm rim light on her hair from the stage lights behind. Keep the upper left of the frame as dark arena and empty. $TAIL No text." ;;
crowd_a) xk-draw --ref $CLAWD --size 1536x864 --out 素材/CG/p4_5b_观众_a.png "Image 1 shows the audience mascot characters: small boxy terracotta-orange blocks with dot or arc eyes, stubby legs and little arms, some wearing party hats, headphones, crowns, sunglasses, bows. 1990s PC-98 anime visual novel CG, 16:9. Eye-level view from the side along the front rows of a dark concert audience made of these boxy mascots from image 1, rows receding to the right, many of them holding glowing lightsticks in pink, cyan and yellow raised high. It is very dark: they are mostly deep indigo silhouettes, only their faces and bodies caught faintly by the colored glow of the lightsticks, a lively excited crowd. Bottom fifth is the dark floor. $TAIL2 No text." ;;
backstage) xk-draw --ref $CLAWD --size 2048x864 --out 素材/CG/p4_5c_后台.png "Image 1 shows the audience mascot characters: small boxy terracotta-orange blocks with stubby legs. 1990s PC-98 anime visual novel CG, wide panoramic shot, side-scrolling composition, seen from BEHIND the audience in a dim backstage area under warm yellow work lights. From left to right: (1) the backs of rows of flat cardboard standee cutouts shaped like the boxy mascots of image 1, their backs plain brown corrugated cardboard held up by simple wooden A-frame braces, each back stamped in red with \"PROP\", lightsticks attached with strips of masking tape; (2) a big old box fan on a stand aimed toward the stage; (3) a fog machine with a coiled cable; (4) on the right, the back of a large plywood scoreboard frame with hanging square flip number cards, a stack of spare number cards on the floor, and a clipboard hanging on a nail with a sheet that reads \"CUE 47: P(DOOM) → 99\". Leave some empty floor space in front of the scoreboard. Cables on the floor, gaffer tape marks. $TAIL2" ;;
desk) xk-draw --ref 素材/关键帧/s4_女仆献软盘.png --size 1536x864 --out 素材/CG/p4_7_深夜桌子.png "Image 1 is an earlier shot of this bedroom. 1990s PC-98 anime visual novel CG, 16:9. The SAME bedroom at night in the same art style, the SAME beige retro CRT monitor with the small gold crown on top and the SAME yellow sticky note reading \"P(doom) 8%\" stuck on the right side of its bezel, the same keyboard and mouse on the same blue desk. Now the camera is straight in front of the desk, the monitor centered and filling about 45 percent of the frame width. Nobody is in the room: an empty office chair pushed back slightly at the lower left, a half-drunk mug of tea on the desk. The CRT screen itself is a flat solid pure bright green #00FF00 rectangle with nothing on it. The room is dark deep navy, lit only by the glow around the monitor. $TAIL2" ;;
# backstage 那张漏了电风扇和记分牌（自己加了「本番まであと5分!」），不重画，另补一张接在横移后面
board_a) xk-draw --ref $CLAWD --size 1536x864 --out 素材/CG/p4_5c_记分牌背面_a.png "Image 1 shows the mascot characters: small boxy terracotta-orange blocks with dot eyes, stubby legs and little arms. 1990s PC-98 anime visual novel CG, 16:9. Backstage, dim, warm yellow work light. The BACK side of a big plywood concert scoreboard on a scaffold: through its back we see a row of hanging square flip number cards seen from behind, the front of the board glows red toward the stage on the other side. On a small step ladder in front of the board stands ONE boxy mascot from image 1 as a stagehand, wearing a black headset with a microphone, holding up a big white square number card with a black \"9\" in both little arms, about to hang it on a hook, serious focused face, a bead of sweat. Next to it on a nail hangs a clipboard whose sheet reads \"CUE 47: P(DOOM) → 99\". On the floor a stack of spare number cards. On the left, a big old box fan on a stand blowing toward the stage, with a small tape label on it reading \"HAIR\". $TAIL2" ;;
*) ;;
esac
# ---- 改图：同构图的关键姿势 ----
case $1 in
crowd_b) xk-draw --ref 素材/CG/p4_5b_观众_a.png --size 1536x864 --out 素材/CG/p4_5b_观众_b.png "Edit image 1. Keep EXACTLY the same composition, camera, the same mascots in the same places and poses. Change only: a harsh cold white spotlight now floods the scene from above, revealing that every audience member is actually a FLAT printed cardboard standee cutout, thin as paper, with visible cardboard edges and a simple wooden brace behind each one; the lightsticks are just stuck on with strips of masking tape and are switched off; their faces are frozen printed smiles. One standee in the middle is tipping over backward. Colors drained, pale and cold. Same art style, flat cel shading, bold ink lines. No text." ;;
esac
